delete from `usermaint`;
delete from `doctype`;
update #stockt2 set skunum = concat('|',skunum,'|') where skunum != 'NONE' and skunum not like '|%';
update #stockt2 set link = if(link='1','1000',(if(link='2','0200',(if(link='3','0030',if(link='0','0000',link))))));
update #links set ltype = if(ltype='1','1000',(if(ltype='2','0200',(if(ltype='3','0030',if(ltype='0','0000',ltype))))));
delete from #links where (select descr from #stockt2 where #stockt2.code = #links.link) is null;
update #creditors set ctype = 'Supplier' where ctype = 'Suplier';
CREATE TABLE if not exists smslist (`listName` varchar(100) default NULL,`QStr` varchar(1000) default NULL);
CREATE VIEW if  not exists`saleshist` AS (select `m1sttrans`.`date` AS `date`,`m1sttrans`.`code` AS `code`,sum(`m1sttrans`.`qty` * -1) AS `sales` from `m1sttrans` where `m1sttrans`.`transtype` in ('0','8','4') group by `m1sttrans`.`code`,year(`m1sttrans`.`date`),month(`m1sttrans`.`date`));
CREATE VIEW if  not exists `purchhist` AS (select `m1sttrans`.`date` AS `date`,`m1sttrans`.`code` AS `code`,sum(`m1sttrans`.`qty`) AS `sales` from `m1sttrans` where `m1sttrans`.`transtype` in ('6','9') group by `m1sttrans`.`code`,year(`m1sttrans`.`date`),month(`m1sttrans`.`date`));
CREATE VIEW if  not exists brpurchhist AS (select branch AS branch, date AS date, code AS code, sum(qty * -1) AS sales from sttrans where transtype in ('0','8') group by branch,code,year(date),month(date));
CREATE VIEW if  not exists brsaleshist AS (select branch AS branch, date AS date, code AS code, sum(qty * -1) AS sales from sttrans where transtype in ('0','8') group by branch,code,year(date),month(date));
